/*
 * OpenSSL 3.4.1's integer SHA-256 block function, as the single-block big-endian copy
 * harness/linux/shim/openssl-armv4/sha256-armv4-be.S (generated by make_be_variant.py), assembled
 * for the Cortex-M33: GCC defines __thumb2__ for this target, so OpenSSL's source selects
 * its Thumb-2 encoding; __ARM_ARCH__ 7 selects its word loads with rev (the M33 allows
 * unaligned word loads); arm_arch.h keeps __ARM_MAX_ARCH__ below 7, which leaves out the
 * NEON and ARMv8 code. The function is named sha2_256_compress_asm.
 */
#define __ARM_ARCH__ 7
#define sha256_block_data_order sha2_256_compress_asm
#include "../harness/linux/shim/openssl-armv4/sha256-armv4-be.S"
